import { useEffect } from "react";
export const useScroll = (callback, active, triggerRef = document.body) => {
    useEffect(() => {
        if (!active || triggerRef === null) {
            return;
        }
        triggerRef.addEventListener("scroll", callback);
        triggerRef.addEventListener("wheel", callback);
        // eslint-disable-next-line consistent-return
        return () => {
            triggerRef.removeEventListener("scroll", callback);
            triggerRef.removeEventListener("wheel", callback);
        };
    }, [callback, active, triggerRef]);
};
